#!/bin/bash
# Part of VRChat Stream. Created by Lokinya (lokinyauv-create).
# Generated by AI (Claude, Anthropic). Apache-2.0.
#
# Runs on the computer that streams (started by vrchat_stream.py, locally or
# over SSH). Mode "browser" (default): opens a separate browser window
# (rootful Xwayland) and captures only it and its sound; optional 2nd argument
# = start page. Mode "screen": screen_capture.py asks the desktop what to share
# (screen, window or region) and captures it with all sound of this computer.
# Either way makes HLS and publishes it through a Cloudflare quick tunnel.
#
# Talks to the window with lines "URL: …", "STATUS: <key>", "ERROR: <key> [details]"
# (the window translates the keys). Stops and cleans up when stdin closes.

# Settings come as env vars from the window (screen_capture.py reads the same)
export W=${W:-1920} H=${H:-1080} FPS=${FPS:-30} KBPS=${KBPS:-4500} \
    AKBPS=${AKBPS:-160} SEG=${SEG:-1} LIST=${LIST:-4} CURSOR=${CURSOR:-0} \
    ENCODER=${ENCODER:-auto} BROWSER=${BROWSER:-auto}
DISP=:77
PORT=8790
SINK=vrchat_stream
DIR="$(dirname "$(readlink -f "$0")")"
RUN=/run/user/$(id -u)/vrchat-stream

MODE=${1:-browser}
START_URL=$2

# shellcheck source=browsers.sh
. "$DIR/browsers.sh"
# Profile of version 1.0.0 (Brave only) — keep its logins
OLD_PROFILE=~/.local/share/vrchat-stream/browser-profile
[ -d "$OLD_PROFILE" ] && [ ! -e "$PROFILES/brave" ] && mkdir -p "$PROFILES" && mv "$OLD_PROFILE" "$PROFILES/brave"

# "stream.sh browsers": what the window's browser list should offer
if [ "$MODE" = browsers ]; then
    echo "BROWSERS: $(installed_browsers | tr '\n' ' ')"
    echo "DEFAULT: $(default_browser)"
    exit 0
fi

# Over SSH there is no desktop environment: find the user's session
export XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR:-/run/user/$(id -u)}
if [ -z "$WAYLAND_DISPLAY" ]; then
    WAYLAND_DISPLAY=$(cd "$XDG_RUNTIME_DIR" && ls wayland-[0-9] 2>/dev/null | head -1)
    export WAYLAND_DISPLAY=${WAYLAND_DISPLAY:-wayland-0}
fi
export DBUS_SESSION_BUS_ADDRESS=${DBUS_SESSION_BUS_ADDRESS:-unix:path=$XDG_RUNTIME_DIR/bus}

say() { echo "$@"; }

# Dependencies
MISSING=
need() { command -v "$1" >/dev/null || MISSING="$MISSING $1"; }
need ffmpeg; need cloudflared; need pactl; need python3; need curl
if [ "$MODE" = screen ]; then
    python3 -c 'import dbus, gi; gi.require_version("Gst", "1.0"); from gi.repository import Gst' \
        2>/dev/null || MISSING="$MISSING python3-dbus/gstreamer-python"
else
    need Xwayland
    if ! pick_browser "$BROWSER"; then
        [ "$BROWSER" = auto ] && MISSING="$MISSING browser" || MISSING="$MISSING $BROWSER"
    fi
fi
if [ -n "$MISSING" ]; then
    say "ERROR: missing$MISSING"
    exit 1
fi
[ -S "$XDG_RUNTIME_DIR/$WAYLAND_DISPLAY" ] || { say "ERROR: no_wayland"; exit 1; }

# H.264 encoder: the first that really works here (a driver may be missing
# even when ffmpeg lists the encoder)
ff_encoder_args() {
    case $1 in
        nvenc) echo "-c:v h264_nvenc -preset p4 -profile:v high -pix_fmt yuv420p" ;;
        vaapi) echo "-vaapi_device /dev/dri/renderD128 -vf format=nv12,hwupload -c:v h264_vaapi" ;;
        x264) echo "-c:v libx264 -preset veryfast -tune zerolatency -pix_fmt yuv420p" ;;
        openh264) echo "-c:v libopenh264 -pix_fmt yuv420p" ;;
    esac
}
if [ "$ENCODER" = auto ]; then
    CANDIDATES="nvenc vaapi x264 openh264"
else
    CANDIDATES="$ENCODER nvenc vaapi x264 openh264"
fi
ENC=
for e in $CANDIDATES; do
    # shellcheck disable=SC2046
    if ffmpeg -v error -nostdin -f lavfi -i color=s=320x240:r=30 -frames:v 5 \
        $(ff_encoder_args $e) -f null - >/dev/null 2>&1; then
        ENC=$e; break
    fi
done
[ -n "$ENC" ] || { say "ERROR: no_encoder"; exit 1; }
export ENCODER=$ENC

cleanup() {
    trap - EXIT INT TERM HUP
    say "STATUS: stopping"
    kill $FF_PID $CF_PID $HTTP_PID $INHIBIT_PID 2>/dev/null
    pkill -f -- "(--user-data-dir=|--profile )$PROFILES/" 2>/dev/null
    kill $XW_PID 2>/dev/null
    [ -n "$MOD" ] && pactl unload-module "$MOD" 2>/dev/null
    rm -rf "$RUN"
    [ "$(cat "$PIDFILE" 2>/dev/null)" = $$ ] && rm -f "$PIDFILE"
    exit 0
}
trap cleanup EXIT INT TERM HUP

# Only one stream at a time: stop the previous run and let its cleanup finish
# first, otherwise it deletes this run's folder
PIDFILE=$XDG_RUNTIME_DIR/vrchat-stream.pid
OLD=$(cat "$PIDFILE" 2>/dev/null)
if [ -n "$OLD" ] && [ "$OLD" != $$ ] && kill -0 "$OLD" 2>/dev/null; then
    say "STATUS: stopping_previous"
    kill "$OLD"
    for _ in $(seq 50); do kill -0 "$OLD" 2>/dev/null || break; sleep 0.2; done
fi
echo $$ >"$PIDFILE"

# Leftovers of a run that wasn't cleaned up (e.g. lost connection)
pkill -f "cloudflared tunnel --no-autoupdate --url http://127.0.0.1:$PORT" 2>/dev/null
pkill -f "hls_server.py $RUN" 2>/dev/null
pkill -f "x11grab.*$DISP" 2>/dev/null
pkill -f -- "(--user-data-dir=|--profile )$PROFILES/" 2>/dev/null
pkill -f "Xwayland $DISP" 2>/dev/null
pkill -f "screen_capture.py $RUN" 2>/dev/null
for m in $(pactl list short modules | awk -v s="sink_name=$SINK" '$0 ~ s {print $1}'); do pactl unload-module "$m"; done
sleep 1
rm -rf "$RUN"; mkdir -p "$RUN/hls"

# Keep the computer awake while streaming
if command -v kde-inhibit >/dev/null; then
    kde-inhibit --power sleep infinity >/dev/null 2>&1 &
else
    systemd-inhibit --what=sleep:idle --who="VRChat Stream" --why=Streaming \
        sleep infinity >/dev/null 2>&1 &
fi
INHIBIT_PID=$!

python3 "$DIR/hls_server.py" "$RUN/hls" $PORT &
HTTP_PID=$!

if [ "$MODE" = screen ]; then
    # Its STATUS:/ERROR: lines go straight to the window
    python3 "$DIR/screen_capture.py" "$RUN/hls" 2>"$RUN/capture.log" &
    FF_PID=$!
else
    say "STATUS: opening_browser"
    MOD=$(pactl load-module module-null-sink sink_name=$SINK \
        sink_properties=device.description="VRChat-Stream")
    Xwayland $DISP -geometry ${W}x${H} -decorate -noreset >"$RUN/xwayland.log" 2>&1 &
    XW_PID=$!
    for _ in $(seq 50); do [ -S /tmp/.X11-unix/X${DISP#:} ] && break; sleep 0.1; done
    launch_browser >"$RUN/browser.log" 2>&1 &

    say "STATUS: starting_capture"
    # shellcheck disable=SC2046
    ffmpeg -hide_banner -loglevel error -nostdin \
        -f x11grab -draw_mouse $CURSOR -framerate $FPS -video_size ${W}x${H} -i $DISP \
        -f pulse -i $SINK.monitor \
        $(ff_encoder_args $ENC) \
        -b:v ${KBPS}k -maxrate ${KBPS}k -bufsize $((KBPS * 2))k -g $FPS -bf 0 \
        -c:a aac -b:a ${AKBPS}k -ar 48000 -ac 2 \
        -f hls -hls_time $SEG -hls_list_size $LIST \
        -hls_flags delete_segments+omit_endlist+independent_segments \
        -hls_segment_filename "$RUN/hls/seg%05d.ts" "$RUN/hls/index.m3u8" \
        2>"$RUN/capture.log" &
    FF_PID=$!
fi

say "STATUS: making_link"
cloudflared tunnel --no-autoupdate --url http://127.0.0.1:$PORT >"$RUN/cloudflared.log" 2>&1 &
CF_PID=$!
URL=
for _ in $(seq 60); do
    URL=$(grep -o 'https://[a-z0-9-]*\.trycloudflare\.com' "$RUN/cloudflared.log" | head -1)
    [ -n "$URL" ] && break
    kill -0 $CF_PID 2>/dev/null || break
    sleep 1
done
if [ -z "$URL" ]; then
    say "ERROR: cloudflare_failed $(tail -2 "$RUN/cloudflared.log" | tr '\n' ' ')"
    exit 1
fi
# The tunnel hostname needs a few seconds before it resolves everywhere.
# Check through public DNS: asking too early makes resolvers cache "no such
# name" for minutes, and viewers would get nothing.
for _ in $(seq 45); do
    curl -sf -m 8 --doh-url https://1.1.1.1/dns-query -o /dev/null "$URL/" && break
    sleep 2
done
sleep 3
say "URL: $URL/index.m3u8"
if [ "$MODE" = screen ] && [ ! -s "$RUN/hls/index.m3u8" ]; then
    say "STATUS: link_ready_pick"
else
    say "STATUS: streaming"
fi

# Keep running until the window closes the connection; report crashes
while true; do
    if ! kill -0 $FF_PID 2>/dev/null; then
        [ "$MODE" = screen ] || say "ERROR: capture_stopped $(tail -2 "$RUN/capture.log" | tr '\n' ' ')"
        exit 1
    fi
    if ! kill -0 $CF_PID 2>/dev/null; then
        say "ERROR: tunnel_stopped"; exit 1
    fi
    read -r -t 5 line; rc=$?
    [ $rc -eq 0 ] || [ $rc -gt 128 ] || exit 0   # EOF → the window is gone
done
